from intervals import merge_intervals
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---------- helpers: obviously-correct reference model ----------

def _reference(intervals):
    pts = set()
    for s, e in intervals:
        if s > e:
            raise ValueError
        for p in range(s, e + 1):
            pts.add(p)
    if not pts:
        return []
    sp = sorted(pts)
    out = []
    cs, ce = sp[0], sp[0]
    for p in sp[1:]:
        if p == ce + 1:
            ce = p
        else:
            out.append((cs, ce))
            cs, ce = p, p
    out.append((cs, ce))
    return out


def _coverage(intervals):
    pts = set()
    for s, e in intervals:
        for p in range(s, e + 1):
            pts.add(p)
    return pts


small_int = st.integers(min_value=-10, max_value=10)
valid_pair = st.builds(
    lambda a, b: (min(a, b), max(a, b)), small_int, small_int
)
valid_lists = st.lists(valid_pair, max_size=8)


# ---------- spec examples ----------

def test_example_basic():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]

def test_example_touching_merges():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]

def test_example_adjacent_stays_separate():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]

def test_example_unsorted_input_sorted_output():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]

def test_example_empty():
    assert merge_intervals([]) == []

def test_example_invalid_raises():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# ---------- explicit boundary examples ----------

def test_touching_at_single_point_merges():
    assert merge_intervals([(1, 2), (2, 3)]) == [(1, 3)]

def test_duplicate_single_points_merge():
    assert merge_intervals([(2, 2), (2, 2)]) == [(2, 2)]

def test_single_point_touching_end_merges():
    assert merge_intervals([(1, 3), (3, 3)]) == [(1, 3)]

def test_single_point_adjacent_does_not_merge():
    assert merge_intervals([(1, 3), (4, 4)]) == [(1, 3), (4, 4)]

def test_contained_interval_absorbed():
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]

def test_identical_intervals_collapse():
    assert merge_intervals([(1, 5), (1, 5)]) == [(1, 5)]

def test_transitive_chain_collapses():
    assert merge_intervals([(1, 2), (2, 3), (3, 4)]) == [(1, 4)]

def test_transitive_chain_with_gap_stays_split():
    assert merge_intervals([(1, 2), (2, 3), (5, 6)]) == [(1, 3), (5, 6)]

def test_negative_touching_merges():
    assert merge_intervals([(-5, -3), (-3, -1)]) == [(-5, -1)]

def test_negative_adjacent_stays_separate():
    assert merge_intervals([(-5, -3), (-2, -1)]) == [(-5, -3), (-2, -1)]

def test_single_interval_unchanged():
    assert merge_intervals([(2, 2)]) == [(2, 2)]
    assert merge_intervals([(0, 5)]) == [(0, 5)]

def test_invalid_anywhere_raises():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 4)])
    with pytest.raises(ValueError):
        merge_intervals([(5, 4), (1, 2)])
    with pytest.raises(ValueError):
        merge_intervals([(0, 0), (3, 2), (1, 1)])


# ---------- structural properties ----------

@given(valid_lists)
def test_output_sorted_by_start(intervals):
    out = merge_intervals(intervals)
    assert [s for s, _ in out] == sorted(s for s, _ in out)

@given(valid_lists)
def test_output_strictly_disjoint(intervals):
    out = merge_intervals(intervals)
    for (s1, e1), (s2, e2) in zip(out, out[1:]):
        assert s2 > e1

@given(valid_lists)
def test_output_gap_is_at_least_one(intervals):
    # adjacent (gap of exactly 1 between end and next start) must stay separate,
    # so disjointness means s2 >= e1 + 2 is NOT required; s2 >= e1+1 suffices.
    # Here check strict inequality from spec: start > prev end.
    out = merge_intervals(intervals)
    for (s1, e1), (s2, e2) in zip(out, out[1:]):
        assert s2 - e1 >= 1

@given(valid_lists)
def test_output_valid_intervals(intervals):
    out = merge_intervals(intervals)
    for s, e in out:
        assert isinstance(s, int) and isinstance(e, int)
        assert s <= e

@given(valid_lists)
def test_coverage_preserved(intervals):
    out = merge_intervals(intervals)
    assert _coverage(out) == _coverage(intervals)

@given(valid_lists)
def test_equivalence_to_set_reference_model(intervals):
    assert merge_intervals(intervals) == _reference(intervals)

@given(valid_lists)
def test_no_further_merge_possible(intervals):
    out = merge_intervals(intervals)
    for i in range(len(out)):
        for j in range(i + 1, len(out)):
            s1, e1 = out[i]
            s2, e2 = out[j]
            # share no point: intervals must be disjoint
            assert e1 < s2 or e2 < s1

@given(valid_lists)
def test_idempotence(intervals):
    once = merge_intervals(intervals)
    assert merge_intervals(once) == once
    assert merge_intervals(list(once)) == once

@given(valid_lists)
def test_order_independence(intervals):
    out1 = merge_intervals(intervals)
    out2 = merge_intervals(list(reversed(intervals)))
    assert out1 == out2

@given(valid_lists)
def test_duplicates_do_not_change_result(intervals):
    assert merge_intervals(intervals + intervals) == merge_intervals(intervals)

@given(valid_lists)
def test_output_is_new_list_of_tuples(intervals):
    out = merge_intervals(intervals)
    assert isinstance(out, list)
    for item in out:
        assert isinstance(item, tuple)
    # mutating output must not affect a fresh call; and output is not the input object
    assert out is not intervals

def test_input_list_not_mutated():
    inp = [(3, 5), (1, 2), (2, 4)]
    snapshot = list(inp)
    merge_intervals(inp)
    assert inp == snapshot

@given(valid_lists)
def test_input_list_and_elements_not_mutated(intervals):
    snapshot_list = list(intervals)
    snapshot_elems = [tuple(x) for x in intervals]
    ids = [id(x) for x in intervals]
    merge_intervals(intervals)
    assert intervals == snapshot_list
    assert [tuple(x) for x in intervals] == snapshot_elems
    assert [id(x) for x in intervals] == ids

@given(valid_lists)
def test_output_length_never_exceeds_input(intervals):
    assert len(merge_intervals(intervals)) <= len(intervals)

@given(st.lists(valid_pair, min_size=1, max_size=6))
def test_every_output_endpoint_covered_by_input(intervals):
    out = merge_intervals(intervals)
    cov = _coverage(intervals)
    for s, e in out:
        assert s in cov
        assert e in cov

@given(valid_lists)
def test_single_point_intervals_preserved_unless_merged(intervals):
    out = merge_intervals(intervals)
    cov_in = _coverage(intervals)
    cov_out = _coverage(out)
    assert cov_in == cov_out
    for s, e in out:
        assert s <= e


# ---------- touching vs adjacent metamorphic ----------

@given(st.integers(min_value=-20, max_value=20), st.integers(min_value=0, max_value=5), st.integers(min_value=0, max_value=5))
def test_touching_vs_adjacent_boundary(a, lb, lc):
    # [a-lb, a] and [a, a+lc] touch at a -> must merge
    # [a-lb, a] and [a+1, a+1+lc] adjacent -> must not merge into one
    left = (a - lb, a)
    touch = (a, a + lc)
    adj = (a + 1, a + 1 + lc)
    assert merge_intervals([left, touch]) == [(min(left[0], touch[0]), max(left[1], touch[1]))]
    assert merge_intervals([left, adj]) == sorted([left, adj])

@given(st.integers(min_value=-20, max_value=20))
def test_single_point_touch_both_sides(x):
    assert merge_intervals([(x, x), (x - 1, x - 1)]) == [(x - 1, x - 1), (x, x)]
    assert merge_intervals([(x, x), (x, x)]) == [(x, x)]
    assert merge_intervals([(x - 5, x + 5), (x, x)]) == [(x - 5, x + 5)]
